      "ضغط واطي + مفيش bleb + AC مسطحة",
      "اعملي Seidel",
      "لو فيه leak",
      "aqueous suppressant",
      "bandage lens أو خياطة",
      "AC ضحلة",
      "Atropine 1% أو Plegica 1% ×3",
      "Pred Forte",
      "blebitis grade 1–2",
      "Vigamox كل ساعة ± Avalox 400",
      "grade 3 = endophthalmitis",
      "tap and inject"
